// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

interface IImplementation {
    function execute(bytes calldata data) external returns (bytes memory);
    function healthCheck() external view returns (bool);
}

contract CircuitBreakerProxy {
    enum State { CLOSED, OPEN, HALF_OPEN }

    State public circuitState;
    uint256 public failureCount;
    uint256 public lastFailureTime;
    uint256 public constant FAILURE_THRESHOLD = 5;
    uint256 public constant RECOVERY_TIMEOUT = 300;
    uint256 public constant PROBE_INTERVAL = 60;

    address public owner;
    address public implementation;
    address public pendingImplementation;

    mapping(address => bool) public authorizedCallers;
    mapping(bytes4 => bool) public blockedSelectors;

    event CircuitOpened(uint256 timestamp, uint256 failures);
    event CircuitClosed(uint256 timestamp);
    event ImplementationUpgraded(address indexed oldImpl, address indexed newImpl);
    event ProbeResult(bool success);

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    modifier onlyAuthorized() {
        require(authorizedCallers[msg.sender] || msg.sender == owner, "Not authorized");
        _;
    }

    modifier circuitNotOpen() {
        if (circuitState == State.OPEN) {
            if (block.timestamp - lastFailureTime >= RECOVERY_TIMEOUT) {
                circuitState = State.HALF_OPEN;
            } else {
                revert("Circuit is open");
            }
        }
        _;
    }

    constructor(address _implementation) {
        owner = msg.sender;
        implementation = _implementation;
        circuitState = State.CLOSED;
        authorizedCallers[msg.sender] = true;
    }

    function upgradeImplementation(address _newImpl) external onlyOwner {
        require(_newImpl != address(0), "Zero address");
        pendingImplementation = _newImpl;
    }

    function finalizeUpgrade() external onlyOwner {
        require(pendingImplementation != address(0), "No pending upgrade");
        address oldImpl = implementation;
        implementation = pendingImplementation;
        pendingImplementation = address(0);

        // Reset circuit state on upgrade
        circuitState = State.CLOSED;
        failureCount = 0;

        emit ImplementationUpgraded(oldImpl, implementation);
    }

    function emergencyPause() external onlyOwner {
        circuitState = State.OPEN;
        lastFailureTime = block.timestamp;
        emit CircuitOpened(block.timestamp, failureCount);
    }

    function probeHealth() external onlyAuthorized returns (bool) {
        require(circuitState == State.HALF_OPEN || circuitState == State.OPEN, "Not in recovery");

        address _impl = implementation;
        bool success;

        try IImplementation(_impl).healthCheck() returns (bool healthy) {
            success = healthy;
        } catch {
            success = false;
        }

        emit ProbeResult(success);

        if (success) {
            circuitState = State.CLOSED;
            failureCount = 0;
            emit CircuitClosed(block.timestamp);
        } else {
            circuitState = State.OPEN;
            lastFailureTime = block.timestamp;
        }

        return success;
    }

    function forwardCall(bytes calldata data) external onlyAuthorized circuitNotOpen returns (bytes memory) {
        require(data.length >= 4, "Invalid calldata");
        bytes4 selector = bytes4(data[:4]);
        require(!blockedSelectors[selector], "Selector blocked");

        // Cache implementation address before call
        address _impl = implementation;

        (bool success, bytes memory result) = _impl.call(data);

        if (!success) {
            _recordFailure();
            // Bubble up the revert reason
            if (result.length > 0) {
                assembly {
                    revert(add(result, 32), mload(result))
                }
            }
            revert("Call failed");
        }

        // Reset failure count on success in half-open state
        if (circuitState == State.HALF_OPEN) {
            circuitState = State.CLOSED;
            failureCount = 0;
            emit CircuitClosed(block.timestamp);
        }

        return result;
    }

    function _recordFailure() internal {
        failureCount++;
        lastFailureTime = block.timestamp;

        if (failureCount >= FAILURE_THRESHOLD) {
            circuitState = State.OPEN;
            emit CircuitOpened(block.timestamp, failureCount);
        }
    }

    function setAuthorized(address caller, bool status) external onlyOwner {
        authorizedCallers[caller] = status;
    }

    function blockSelector(bytes4 selector, bool status) external onlyOwner {
        blockedSelectors[selector] = status;
    }

    // Allow receiving ETH
    receive() external payable {}

    function withdrawETH(address payable to, uint256 amount) external onlyOwner {
        require(to != address(0), "Zero address");
        (bool sent, ) = to.call{value: amount}("");
        require(sent, "ETH transfer failed");
    }
}
